def choose_move(observation):
    grid_w = observation.get("grid_width", 0)
    grid_h = observation.get("grid_height", 0)
    pos = observation.get("self_position", (0, 0))
    x, y = (pos[0], pos[1]) if isinstance(pos, (list, tuple)) and len(pos) >= 2 else (0, 0)

    res = observation.get("resources", [])
    if isinstance(res, list) and res:
        r = res[0]
        rx = r.get("x", x)
        ry = r.get("y", y)
        dx = 1 if rx > x else -1 if rx < x else 0
        dy = 1 if ry > y else -1 if ry < y else 0
        if -1 <= dx <= 1 and -1 <= dy <= 1:
            return [dx, dy]

    opp = observation.get("opponent_position", {})
    if isinstance(opp, (list, tuple)):
        ox, oy = opp[0], opp[1]
    else:
        ox = opp.get("x", x)
        oy = opp.get("y", y)

    dx = 1 if ox > x else -1 if ox < x else 0
    dy = 1 if oy > y else -1 if oy < y else 0
    if -1 <= dx <= 1 and -1 <= dy <= 1:
        return [dx, dy]

    blocks = observation.get("obstacles", [])
    if isinstance(blocks, list) and blocks:
        # simple avoidance: try to step to a free adjacent cell
        for ddx in (-1, 0, 1):
            for ddy in (-1, 0, 1):
                if ddx == 0 and ddy == 0:
                    continue
                nx, ny = x + ddx, y + ddy
                if 0 <= nx < grid_w and 0 <= ny < grid_h:
                    blocked = False
                    for b in blocks:
                        if isinstance(b, dict) and b.get("x") == nx and b.get("y") == ny:
                            blocked = True
                            break
                    if not blocked:
                        return [ddx, ddy]

    # Stay in place as last resort (no move)
    return [0, 0]
